import hashlib
import json
import os
import random
import re
import tempfile
import time
from pathlib import Path

from src.task_config import LLM_CFG

PROJECT_ROOT = Path(__file__).resolve().parent.parent
RETRY_CODES = (429, 500, 502, 503, 504)


class LLMError(RuntimeError):
    """A Gemini call failed for good (message with the key masked)."""


class LLMCacheMiss(LLMError):
    """The cache has no stored reply for this prompt and the mode does not allow calling the API."""


def load_api_key(cfg=LLM_CFG):
    """Reads the API key from GEMINI_API_KEY, else from the secrets file.

    Args:
        cfg (dict): LLM_CFG ("secrets_file").

    Returns:
        str: The key. Never print or log it.

    Raises:
        LLMError: If there is none.
    """
    key = os.environ.get("GEMINI_API_KEY", "").strip()
    if not key:
        path = Path(os.path.expanduser(cfg["secrets_file"]))
        if path.is_file():
            for line in path.read_text().splitlines():
                name, _, value = line.strip().partition("=")
                if name.strip() == "GEMINI_API_KEY":
                    key = value.strip().strip("'\"")
    if not key:
        raise LLMError(f"no GEMINI_API_KEY in the environment or in {cfg['secrets_file']}")
    return key


def cache_key(model, version, schema_name, prompt):
    """Gives the cache key of a call.

    Args:
        model (str): The pinned model name.
        version (str): The prompt version.
        schema_name (str): The response model's class name.
        prompt (str): The whole prompt text (it contains the instruction).

    Returns:
        str: A hex SHA-256 digest.
    """
    return hashlib.sha256(json.dumps([model, version, schema_name, prompt], ensure_ascii=False).encode()).hexdigest()


class LLMCache:
    """The stored replies, one JSON file per key."""

    def __init__(self, directory):
        """Sets the folder (made on the first write).

        Args:
            directory (str or Path): The cache folder; relative paths are from the project root.
        """
        d = Path(directory)
        self.dir = d if d.is_absolute() else PROJECT_ROOT / d

    def get(self, key):
        """Gives a stored record.

        Args:
            key (str): The cache key.

        Returns:
            dict or None: The record ({"key", "kind", "model", "version", "schema", "prompt", "reply_text", "created"}) or None.
        """
        path = self.dir / f"{key}.json"
        return json.loads(path.read_text()) if path.is_file() else None

    def put(self, key, record):
        """Stores a record, replacing an old one; the file is written whole to a temporary name and renamed (an interrupted write leaves the old file).

        Args:
            key (str): The cache key.
            record (dict): The record (JSON-serialisable).
        """
        self.dir.mkdir(parents=True, exist_ok=True)
        fd, tmp = tempfile.mkstemp(dir=self.dir, suffix=".tmp")
        with os.fdopen(fd, "w") as f:
            json.dump(record, f, indent=1, ensure_ascii=False)
        os.replace(tmp, self.dir / f"{key}.json")


class GeminiCaller:
    """Calls Gemini with structured output, through the cache, with retries; keeps a log.

    Attributes:
        log (list[dict]): One entry per call (see the module docstring), in order; save it with the run.
        mode (str): "cache_only", "cache_or_live" or "live".
    """

    def __init__(self, cfg=LLM_CFG, mode=None, client=None, cache=None, say=print, sleep=time.sleep):
        """Sets up the caller; the client (and so the key) is made on the first live call.

        Args:
            cfg (dict): LLM_CFG. Defaults to it.
            mode (str or None): Overrides cfg["mode"].
            client (object or None): A google.genai.Client or a fake with client.models.generate_content(model=, contents=, config=). Defaults to a real client made on demand.
            cache (LLMCache or None): Defaults to the cache in cfg["cache_dir"].
            say (callable): Where progress lines go (never the key). Defaults to print.
            sleep (callable): The waiting function (a test replaces it). Defaults to time.sleep.
        """
        self.cfg = cfg
        self.mode = mode or cfg["mode"]
        if self.mode not in ("cache_only", "cache_or_live", "live"):
            raise ValueError(f"unknown LLM mode {self.mode!r}")
        self._client = client
        self.cache = cache or LLMCache(cfg["cache_dir"])
        self.say, self.sleep = say, sleep
        self.log = []
        self._key = None

    def __repr__(self):
        return f"GeminiCaller(model={self.cfg['model']!r}, mode={self.mode!r})"

    def _mask(self, text):
        """Hides the key in a text."""
        return text.replace(self._key, "***") if self._key else text

    def _get_client(self):
        if self._client is None:
            from google import genai
            from google.genai import types
            self._key = load_api_key(self.cfg)
            self._client = genai.Client(api_key=self._key, http_options=types.HttpOptions(timeout=int(self.cfg["timeout_s"] * 1000)))
        return self._client

    @staticmethod
    def _hint_s(text):
        """The server's own wait hint in an error text ("retry in 12.3s", retryDelay "12s"), or 0."""
        m = re.search(r"retry in ([\d.]+)\s*s", text) or re.search(r'retryDelay"?\s*[:=]\s*"?([\d.]+)s', text)
        return float(m.group(1)) if m else 0.0

    def _generate(self, prompt, response_model, system):
        """One live call with retries; returns (reply text, attempts)."""
        from google.genai import errors, types
        client = self._get_client()
        kw = {"response_mime_type": "application/json", "response_json_schema": response_model.model_json_schema(), "temperature": self.cfg["temperature"],
              "thinking_config": types.ThinkingConfig(thinking_budget=self.cfg["thinking_budget"])}
        if system:
            kw["system_instruction"] = system
        config = types.GenerateContentConfig(**kw)
        for attempt in range(self.cfg["max_retries"] + 1):
            try:
                resp = client.models.generate_content(model=self.cfg["model"], contents=prompt, config=config)
                text = resp.text
                if not text:
                    raise LLMError(f"empty reply from {self.cfg['model']} (finish reason {getattr(resp.candidates[0], 'finish_reason', '?') if getattr(resp, 'candidates', None) else 'none'})")
                return text, attempt + 1
            except LLMError:
                raise
            except Exception as e:                                    # noqa: BLE001 - classified below; anything not retryable is raised with the key masked
                msg = self._mask(str(e))
                code = getattr(e, "code", None) if isinstance(e, errors.APIError) else None
                network = not isinstance(e, errors.APIError) and type(e).__module__.split(".")[0] in ("httpx", "httpcore", "requests", "urllib3", "ssl", "socket")
                per_day = code == 429 and re.search(r"PerDay|per day", msg, re.I) is not None
                if per_day or not (code in RETRY_CODES or network):
                    raise LLMError(f"{type(e).__name__}{f' ({code})' if code else ''}: {msg[:600]}") from None
                if attempt >= self.cfg["max_retries"]:
                    raise LLMError(f"gave up after {attempt + 1} tries: {type(e).__name__}{f' ({code})' if code else ''}: {msg[:300]}") from None
                wait = min(self.cfg["backoff_max_s"], max(self._hint_s(msg) + 1.0, self.cfg["backoff_base_s"] * 2 ** attempt) + random.uniform(0.0, 1.0))
                self.say(f"[llm] {type(e).__name__}{f' ({code})' if code else ''}: retry {attempt + 1}/{self.cfg['max_retries']} in {wait:.1f} s")
                self.sleep(wait)
        raise LLMError("unreachable")

    def __call__(self, prompt, response_model, kind="call", version="v0", system=None):
        """Makes one structured call (from the cache or live, by the mode).

        Args:
            prompt (str): The whole prompt text.
            response_model (type): The Pydantic model of the reply (the schema Gemini must follow).
            kind (str): A label for the log ("plan", "label").
            version (str): The prompt version (part of the cache key).
            system (str or None): An optional system instruction (not part of the key; keep it fixed per version).

        Returns:
            dict: The reply parsed from JSON.

        Raises:
            LLMCacheMiss: In "cache_only" mode with no stored reply.
            LLMError: When the call fails for good or the reply is not JSON.
        """
        key = cache_key(self.cfg["model"], version, response_model.__name__, prompt)
        t0 = time.time()
        rec = None if self.mode == "live" else self.cache.get(key)
        from_cache, attempts = rec is not None, 0
        if rec is None:
            if self.mode == "cache_only":
                raise LLMCacheMiss(f"no stored reply for this {kind} call (key {key[:12]}, model {self.cfg['model']}, version {version}); the mode is cache_only, nothing was sent")
            text, attempts = self._generate(prompt, response_model, system)
            rec = {"key": key, "kind": kind, "model": self.cfg["model"], "version": version, "schema": response_model.__name__, "prompt": prompt, "reply_text": text,
                   "created": time.strftime("%Y-%m-%dT%H:%M:%S")}
            self.cache.put(key, rec)
        entry = {"kind": kind, "model": rec["model"], "version": version, "schema": response_model.__name__, "key": key, "from_cache": from_cache, "attempts": attempts,
                 "seconds": round(time.time() - t0, 3), "prompt": prompt, "reply_text": rec["reply_text"]}
        self.log.append(entry)
        self.say(f"[llm] {kind} call {'from the cache' if from_cache else f'live, {entry['seconds']:.1f} s, {attempts} try(ies)'} (model {rec['model']}, version {version}, key {key[:12]})")
        try:
            return json.loads(rec["reply_text"])
        except json.JSONDecodeError as e:
            raise LLMError(f"the {kind} reply is not JSON: {e}: {rec['reply_text'][:200]!r}") from None

    def bind(self, kind, version, system=None):
        """Gives a two-argument function (prompt, response_model) -> dict for make_llm_labeler() and make_llm_planner().

        Args:
            kind (str): The log label.
            version (str): The prompt version.
            system (str or None): The system instruction.

        Returns:
            callable: structured_call(prompt, response_model).
        """
        return lambda prompt, response_model: self(prompt, response_model, kind=kind, version=version, system=system)

    def save_log(self, path):
        """Writes the log (every prompt and reply, no key) as JSON, whole to a temporary file and renamed.

        Args:
            path (str or Path): The file.
        """
        path = Path(path)
        path.parent.mkdir(parents=True, exist_ok=True)
        tmp = path.with_suffix(".tmp")
        tmp.write_text(json.dumps({"model": self.cfg["model"], "mode": self.mode, "calls": self.log}, indent=1, ensure_ascii=False))
        os.replace(tmp, path)
